        public bool DeleteMasterTag(string Branch, double TagNumber, int NextNumber, string UserID, double MasterTag)
        {
            string JuilanDate;
            string CTime;
            if (Branch.Trim() == "73W01")
            {
                JuilanDate = "1" + DateTime.Now.ToString("yy") + DateTime.Now.AddHours(-2).DayOfYear.ToString().PadLeft(3, '0');
                CTime = DateTime.Now.AddHours(-2).ToString("HHmmss");
            }
            else
            {
                JuilanDate = "1" + DateTime.Now.ToString("yy") + DateTime.Now.DayOfYear.ToString().PadLeft(3, '0');
                CTime = DateTime.Now.ToString("HHmmss");
            }

            SqlConnection cnJDE = new SqlConnection(GetConnectionString());

            string SQLInsert = $"insert into {GetFullTableName("F56PI01H")} ";
            SQLInsert += $"select {NextNumber},PIMCU,PIITM,PILITM,'DELETED',PILOCN,PITGG,PITRQT,PIUOM,PIGNUM1,PIGNUM2,PIGNUM3,PIGNUM4,PIGNUM5,PIDL01, ";
            SQLInsert += $"PIDL02,PIDL03,PIUSER,PIPID,PIJOBN,PIUPMJ,PITDAY, '{UserID}', {JuilanDate},{CTime} ";
            SQLInsert += $"from {GetFullTableName()} where pimcu = '{Branch}' and pitgg = {TagNumber} or pignum2 = {MasterTag}";

            Log.Debug($"<***>SQLInsert = {SQLInsert}");

            SqlCommand cmdInsert = new SqlCommand(SQLInsert, cnJDE);
            try
            {
                cnJDE.Open();
                cmdInsert.ExecuteNonQuery();
                cnJDE.Close();
            }
            catch (SqlException e)
            {
                Log.Debug($"(***) Sql Error {e.Message}");
            }

            string SQL = $"DELETE FROM {GetFullTableName()} WHERE PIMCU = '{Branch}' and (PITGG = {TagNumber} or PIGNUM2 ={MasterTag}) ";

            SqlCommand cmd = new SqlCommand(SQL, cnJDE);
            try
            {
                cnJDE.Open();
                cmd.ExecuteNonQuery();
                cnJDE.Close();
                return true;
            }
            catch (SqlException e)
            {
                Log.Debug($"(***) Sql Error {e.Message}");
                return false;
            }
            finally
            {
                cnJDE.Close();
                cnJDE.Dispose();
            }
        }

